import {parseHocr,HOCR_LIMITS} from './hocr.js';
import {proposedHocr} from './hocr-export.js';
// Read-only hOCR geometry plus explicit adoption into the existing review record.
export function installHocrUI({getSource,getSelection,getSavedReading,getPassageRecords,selectWord}){
 const image=document.getElementById('scan-image'),stage=document.getElementById('image-stage'),heading=document.querySelector('.scan .section-heading');
 const label=document.createElement('label');label.className='file-button';label.append('Open hOCR');const input=document.createElement('input');input.type='file';input.id='hocr-file';input.accept='.html,.hocr,.xhtml,text/html,application/xhtml+xml';label.append(input);heading.append(label);
 const controls=document.createElement('section');controls.id='hocr-controls';controls.hidden=true;controls.setAttribute('aria-label','hOCR passages');
 const pageSelect=document.createElement('select');pageSelect.setAttribute('aria-label','hOCR page');const wordSelect=document.createElement('select');wordSelect.setAttribute('aria-label','hOCR word');
 const activate=document.createElement('button');activate.type='button';activate.textContent='Review selected word';const previous=document.createElement('button');previous.type='button';previous.textContent='Previous word';const next=document.createElement('button');next.type='button';next.textContent='Next / skip word';
 const status=document.createElement('p');status.id='hocr-status';status.setAttribute('role','status');const helper=document.createElement('p');helper.textContent='Open the matching local page image. Image dimensions must match this hOCR page. Coordinates do not prove file identity. Next / skip does not record a review. On image highlights, use arrow keys, Home or End to move focus; Enter or Space opens the focused word.';
 const help=document.createElement('details'),summary=document.createElement('summary');summary.textContent='Source matching and limits';help.append(summary,helper);controls.append(pageSelect,wordSelect,previous,next,activate,help,status);heading.after(controls);
 const question=document.createElement('p');question.id='hocr-question';question.hidden=true;question.setAttribute('role','status');document.querySelector('.transcript').prepend(question);
 let parsed=null,fileInfo=null,fileBytes=null,epoch=0,sourceAtImport=null;const marks=[];let chosen=0;
 const passages=document.createElement('details');passages.id='hocr-passages';passages.hidden=true;const passageSummary=document.createElement('summary'),passageActions=document.createElement('div'),passageCards=document.createElement('div');passages.append(passageSummary,passageActions,passageCards);document.querySelector('.transcript').append(passages);
 let passageStates=new Map();
 function passageState(){const records=getPassageRecords?.()||{revisions:[],reviews:[]},result=new Map(),words=new Map((page()?.words||[]).map(w=>[w.id,w]));for(const r of records.revisions){let pin=r.context.hocr;if(!pin)try{pin=JSON.parse(r.context.method);}catch{}if(pin?.hocrSha256!==fileInfo?.sha256||pin.sourceSha256!==sourceAtImport||pin.pageId!==page()?.id)continue;const word=words.get(pin.wordId);if(!word||word.text!==pin.originalWord||JSON.stringify(word.box)!==JSON.stringify(pin.bbox))continue;const review=records.reviews.filter(v=>v.revisionId===r.id).at(-1);result.set(pin.wordId,{revision:r,reviewDecision:review?.decision||null,state:review&&['disputed','needs_review'].includes(review.decision)?review.decision:'saved'});}return result;}
 function renderPassages(){
  const p=page();if(!p)return;passageStates=passageState();passages.hidden=false;const saved=[...passageStates.values()].filter(v=>v.state==='saved').length;
  passageSummary.textContent='Passages on this page · '+saved+' proposal'+(saved===1?'':'s')+' saved / '+p.words.length+' words';
  passageCards.replaceChildren();
  const indices=new Set(p.words.slice(0,50).map((_,i)=>i));for(const [i,w]of p.words.entries())if(passageStates.has(w.id))indices.add(i);
  for(const i of [...indices].sort((a,b)=>a-b)){
   const w=p.words[i],record=passageStates.get(w.id),state=record?.state||'unworked',card=document.createElement('details'),summary=document.createElement('summary');card.className='hocr-passage-card';card.dataset.wordIndex=String(i);card.dataset.reviewState=state;card.open=['disputed','needs_review'].includes(state);summary.textContent=(i+1)+'. '+w.text+' · '+({saved:'Proposal saved · '+(record?.reviewDecision==='accepted'?'local review accepted':'unreviewed'),unworked:'Not inspected',disputed:'Disputed',needs_review:'Needs review'}[state]);card.append(summary);
   if(record){const text=document.createElement('p');text.textContent='Proposed: '+record.revision.reading.proposed+' · '+record.revision.reading.contributor+'\nReason: '+record.revision.reading.reason;card.append(text);}
   const open=document.createElement('button');open.type='button';open.textContent=record?'Open saved passage':'Work this passage';open.addEventListener('click',()=>adopt(i));card.append(open);passageCards.append(card);
  }
  const note=document.createElement('p');note.textContent='OCR words are candidates, not confirmed errors. Showing the first 50 plus saved passages; the selector and Next unresolved reach all words. Green means a proposal was saved, not approved by the host.';passageCards.append(note);
  for(const mark of marks){const w=p.words[Number(mark.dataset.wordIndex)],state=passageStates.get(w.id)?.state||'unworked';mark.dataset.reviewState=state;mark.setAttribute('aria-label','Review hOCR word '+(Number(mark.dataset.wordIndex)+1)+': '+w.text+(state==='unworked'?'':' · '+(state==='saved'?'Proposal saved':state.replaceAll('_',' '))));}
 }
 for(const [label,action]of [['Expand all',()=>{for(const card of passageCards.querySelectorAll('details'))card.open=true;}],['Collapse saved',()=>{for(const card of passageCards.querySelectorAll('details'))if(card.dataset.reviewState==='saved')card.open=false;}],['Next unresolved',()=>{const p=page();if(!p?.words.length)return;for(let offset=1;offset<=p.words.length;offset++){const index=(Number(wordSelect.value)+offset)%p.words.length;if(passageStates.get(p.words[index].id)?.state!=='saved'){adopt(index);return;}}say('Every word has a saved proposal. This does not mean host approval.');}]]){const button=document.createElement('button');button.type='button';button.textContent=label;button.addEventListener('click',action);passageActions.append(button);}

 const say=s=>{status.textContent=s;};
 function clearMarks(){for(const m of marks)m.remove();marks.length=0;passages.hidden=true;}
 function page(){return parsed?.pages[Number(pageSelect.value)];}
 function matched(){const p=page(),source=getSource();return p&&source?.sha256===sourceAtImport&&image.complete&&!image.hidden&&image.naturalWidth===p.bounds[2]-p.bounds[0]&&image.naturalHeight===p.bounds[3]-p.bounds[1];}
 function position(){if(!matched()){for(const m of marks)m.hidden=true;return;}const p=page();for(const m of marks){const w=p.words[Number(m.dataset.wordIndex)];const [x,y,width,height]=w.normalizedBox;m.hidden=false;m.style.left=(image.offsetLeft+x*image.clientWidth)+'px';m.style.top=(image.offsetTop+y*image.clientHeight)+'px';m.style.width=(width*image.clientWidth)+'px';m.style.height=(height*image.clientHeight)+'px';}}
 function adopt(index){try{if(!matched())throw Error('Open the matching image at the original hOCR pixel dimensions before reviewing a word.');const p=page(),word=p.words[index];selectWord({word,page:p,hocr:fileInfo});chosen=index;wordSelect.value=String(index);question.hidden=false;question.textContent='Check the marked word: '+word.text+' · page '+(p.index+1)+' · '+word.id;for(const m of marks)m.classList.toggle('selected',Number(m.dataset.wordIndex)===index);say('Reviewing '+word.text+' · OCR confidence '+(word.confidence??'not supplied')+'. Add your reason and credit, then save.');document.dispatchEvent(new CustomEvent('reckoner-source-region',{detail:{box:word.normalizedBox,question:'Check '+word.text,activate:true}}));document.dispatchEvent(new CustomEvent('reckoner-hocr-word',{detail:{question:'Check the marked word: '+word.text}}));document.getElementById('proposed').focus({preventScroll:true});}catch(e){say(e.message);}}
 function render(){clearMarks();const p=page();wordSelect.replaceChildren();if(!p)return;chosen=0;for(const [i,w] of p.words.entries()){const o=document.createElement('option');o.value=String(i);o.textContent=(i+1)+': '+w.text;wordSelect.append(o);}activate.disabled=!p.words.length;previous.disabled=next.disabled=!p.words.length;
 // Keep overlaid controls bounded independently of parser limits. Remaining words are selectable.
 for(const [i,w] of p.words.slice(0,2000).entries()){const mark=document.createElement('button');mark.type='button';mark.className='hocr-word-marker';mark.dataset.wordIndex=String(i);mark.tabIndex=i===0?0:-1;mark.addEventListener('focus',()=>{for(const other of marks)other.tabIndex=other===mark?0:-1;});mark.addEventListener('keydown',event=>{let target;if(['ArrowRight','ArrowDown'].includes(event.key))target=(i+1)%marks.length;else if(['ArrowLeft','ArrowUp'].includes(event.key))target=(i-1+marks.length)%marks.length;else if(event.key==='Home')target=0;else if(event.key==='End')target=marks.length-1;else return;event.preventDefault();marks[target]?.focus({preventScroll:true});});mark.setAttribute('aria-label','Review hOCR word '+(i+1)+': '+w.text);mark.addEventListener('click',()=>adopt(i));stage.append(mark);marks.push(mark);}position();renderPassages();passages.open=p.words.length<=12;say(p.words.length+' OCR words. '+(p.words.length>2000?'First 2,000 have image buttons; all words remain in the selector. ':'')+(matched()?'Select a highlight to review.':'Open the matching image before selecting a word.'));}
 function refresh(){
  if(parsed)renderPassages();
  const pin=getSelection?.();if(!parsed||!pin)return;
  if(pin.hocrSha256!==fileInfo?.sha256||pin.sourceSha256!==sourceAtImport){question.hidden=true;say('Opened files differ from the saved source/hOCR hashes. Saved highlight was not restored. A new review requires explicit word selection.');return;}
  const p=parsed.pages[pin.pageIndex],index=p?.words.findIndex(w=>w.id===pin.wordId&&w.text===pin.originalWord&&JSON.stringify(w.box)===JSON.stringify(pin.bbox));
  if(!p||p.id!==pin.pageId||index<0){question.hidden=true;say('Saved region does not match this hOCR page. No highlight restored.');return;}
  if(pageSelect.value!==String(pin.pageIndex)){pageSelect.value=String(pin.pageIndex);render();}
  chosen=index;wordSelect.value=String(index);for(const m of marks)m.classList.toggle('selected',Number(m.dataset.wordIndex)===index);
  question.hidden=false;question.textContent='Saved passage: '+p.words[index].text+' · page '+(p.index+1)+' · '+pin.wordId;
  position();if(matched())document.dispatchEvent(new CustomEvent('reckoner-source-region',{detail:{box:p.words[index].normalizedBox,question:'Saved passage '+p.words[index].text}}));say(matched()?'Saved passage restored from matching image and hOCR hashes. No reading or revision was changed.':'Saved page selected; open the matching local image to restore its highlight.');
 }
 input.addEventListener('change',async()=>{const ticket=++epoch,file=input.files[0];input.value='';if(!file)return;try{if(file.size>HOCR_LIMITS.bytes)throw Error('Use hOCR under 2 MiB; split larger books by page first.');const source=getSource();if(!source?.sha256)throw Error('Open your matching local source image first.');const bytes=await file.arrayBuffer(),raw=new TextDecoder('utf-8',{fatal:true}).decode(bytes),data=parseHocr(raw);const hash=[...new Uint8Array(await crypto.subtle.digest('SHA-256',bytes))].map(n=>n.toString(16).padStart(2,'0')).join('');if(ticket!==epoch||getSource()?.sha256!==source.sha256)throw Error('Source changed during import. Choose the hOCR again.');parsed=data;fileBytes=bytes;fileInfo={name:file.name,sha256:hash,bytes:file.size};sourceAtImport=source.sha256;pageSelect.replaceChildren();for(const p of parsed.pages){const o=document.createElement('option');o.value=String(p.index);o.textContent='Page '+(p.index+1)+' · '+p.id;pageSelect.append(o);}controls.hidden=false;render();refresh();}catch(e){controls.hidden=false;say(e.message);}});
 const exportButton=document.createElement('button');exportButton.type='button';exportButton.textContent='Export saved proposal as hOCR';help.append(exportButton);
 exportButton.onclick=async()=>{exportButton.disabled=true;try{const before=epoch,reading=getSavedReading();if(!fileBytes||!matched())throw Error('Open the matching local image and original hOCR before export.');if(reading.pin.sourceSha256!==sourceAtImport)throw Error('Source image does not match this saved reading.');const result=await proposedHocr(fileBytes,{...reading.pin,proposed:reading.proposed});if(before!==epoch||getSavedReading().revisionId!==reading.revisionId)throw Error('Selection changed during export; retry.');const url=URL.createObjectURL(new Blob([result.text],{type:'application/xhtml+xml'})),a=document.createElement('a');a.href=url;a.download='proposed-correction.hocr.xhtml';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);say('Proposed word-level hOCR download requested. '+result.scope+' Keep the review-history backup for credit, reasons and disputes.');}catch(e){say(e.message);}finally{exportButton.disabled=false;}};
 pageSelect.onchange=render;wordSelect.onchange=()=>{chosen=Number(wordSelect.value);};activate.onclick=()=>adopt(Number(wordSelect.value));
 function move(delta){const p=page();if(!p?.words.length)return;adopt((Number(wordSelect.value)+delta+p.words.length)%p.words.length);}previous.onclick=()=>move(-1);next.onclick=()=>move(1);
 new MutationObserver(()=>{if(parsed)renderPassages();}).observe(document.getElementById('revision-count'),{childList:true,characterData:true,subtree:true});
 image.addEventListener('load',()=>{position();refresh();});const positionObserver=new ResizeObserver(position);positionObserver.observe(image);positionObserver.observe(stage);
 document.getElementById('source-image').addEventListener('change',()=>{epoch++;clearMarks();parsed=null;controls.hidden=true;question.hidden=true;});
 for(const id of ['new-workspace','import-button','load-example','example-image','load-real-example','open-document'])document.getElementById(id)?.addEventListener('click',()=>{epoch++;clearMarks();parsed=null;controls.hidden=true;question.hidden=true;});
 return {refresh};
}
